from textlesson import build
S=dict(cls=6,subj="science",subj_file="science")
build(dict(S,ch="exploring-magnets",topic="poles-and-uses-of-magnets",name_en="Poles and uses of magnets",name_ta="காந்த முனைகளும் பயன்களும்",
 objectives=["Say what happens when poles meet","Name some uses of magnets"],
 story=("The two magnets","Dev had two bar magnets. When he brought two ends close, they pulled together with a click. When he turned one around, they pushed apart.\n\"They are playing push and pull!\" he laughed.\nHis sister said, \"Each end is a pole, and poles have rules.\""),
 explain=["Every magnet has two poles, a north pole and a south pole. The pull is strongest at the poles.","Unlike poles attract each other: north and south pull together. Like poles repel each other: north with north, or south with south, push apart.","A magnet hung freely turns to point north and south, which is why a compass works. Magnets are used in fridge doors, speakers, toys, cranes that lift scrap iron and in compasses."],
 terms=["pole","attract","repel","compass"],
 narr=[("Every magnet has two poles, north and south. The pull is strongest at the poles.","north and south poles"),("Unlike poles attract. Like poles repel.","unlike attract, like repel"),("A freely hanging magnet points north and south. This is how a compass works.","compass"),("Magnets are used in fridge doors, speakers and cranes that lift iron.","uses of magnets")],
 ex=("What happens if you bring the north pole of one magnet near the north pole of another?",[("Both are the same kind of pole, so they are like poles.","North and north are like poles."),("Like poles repel each other.","They push apart."),("So the two magnets push away from each other.","You can feel the push.")]),
 tb=("A friend says a magnet attracts everything it touches. How will you correct this?",["A magnet attracts only magnetic things like iron.","Two like poles even push each other away."],["Thinking a magnet pulls all materials."]),
 summary=["A magnet has a north pole and a south pole.","Unlike poles attract and like poles repel.","Compasses, fridge doors and cranes use magnets."],
 q=[("mcq",1,"r1-poles","How many poles does a magnet have?","two",[("one","A magnet always has two."),("four","A bar magnet has two.")],"North and south."),
    ("tf",1,"r1-strong","A magnet pulls strongest at its poles.",True,"True."),
    ("mcq",2,"r2-unlike","North and south poles","attract each other",[("repel each other","Like poles repel."),("do nothing","They attract.")],"Unlike poles attract."),
    ("tf",2,"r2-like","Two north poles pull together.",False,"False. Like poles repel."),
    ("mcq",3,"r3-comp","A compass needle points","north and south",[("east and west","It points north-south."),("up and down","It stays flat.")],"It is a small magnet."),
    ("short",3,"r3-use","Name one use of a magnet.",["compass","fridge","crane","speaker","toy","door","lock","refrigerator"],"Compasses and fridge doors use magnets."),
    ("mcq",4,"r4-iron","A magnet will attract","an iron nail",[("a wooden stick","Wood is not magnetic."),("a plastic comb","Plastic is not magnetic.")],"Iron is magnetic."),
    ("tf",4,"r4-crane","Cranes with magnets can lift scrap iron.",True,"True.")]))
build(dict(S,ch="living-creatures-exploring-their-characteristics",topic="characteristics-of-living-things",name_en="What makes something alive",name_ta="உயிருள்ளவற்றின் பண்புகள்",
 objectives=["List the signs of life","Tell living from non-living things"],
 story=("The stone and the seed","Neel put a stone and a bean seed on a wet cloth. After a week the seed had a tiny root and shoot. The stone looked the same.\n\"The seed is alive and the stone is not,\" he said.\n\"How do you know?\" asked his teacher. \"The seed grew,\" said Neel."),
 explain=["Living things need food, water and air. They grow, they move in some way, they respond to what is around them, they reproduce and they die.","Plants move too: roots grow down and shoots grow towards light. Animals respond when we touch them or when there is a loud noise.","Non-living things such as stones and chairs do not need food, do not grow by themselves and do not reproduce."],
 terms=["respond","reproduce","non-living","growth"],
 narr=[("Living things need food, water and air.","need food, water, air"),("They grow, move and respond to what is around them.","grow, move, respond"),("They also reproduce, which means making young ones, and they die.","reproduce, die"),("Non-living things like stones do none of these.","non-living")],
 ex=("Is a car living or non-living?",[("A car moves, but it needs fuel made by people and does not grow.","Moving alone is not enough."),("It cannot reproduce or respond like a living thing.","It lacks life signs."),("So a car is non-living.","Moving is not the only sign of life.")]),
 tb=("A friend says clouds are alive because they move. What will you say?",["Clouds do not eat, grow or reproduce.","Moving is not enough to be alive."],["Thinking anything that moves is alive."]),
 summary=["Living things need food, water and air.","They grow, respond, reproduce and die.","Non-living things do not show these signs."],
 q=[("mcq",1,"r1-need","Living things need","food, water and air",[("only toys","Living things need food."),("only light","They need more than light.")],"These are basic needs."),
    ("tf",1,"r1-grow","Living things grow.",True,"True."),
    ("mcq",2,"r2-resp","A plant shoot grows towards light. This shows that plants","respond",[("do not move","They do respond."),("are stones","They are living.")],"Plants respond to light."),
    ("tf",2,"r2-stone","A stone grows slowly like a plant.",False,"False. Stones do not grow."),
    ("mcq",3,"r3-repro","Making young ones is called","reproduction",[("digestion","Digestion is breaking down food."),("breathing","Breathing is taking in air.")],"Living things reproduce."),
    ("short",3,"r3-nonliv","Name one non-living thing.",["stone","chair","table","car","book","pen","rock","bag"],"Stones and chairs are non-living."),
    ("mcq",4,"r4-sign","Which is a sign of life?","responding to touch",[("being heavy","Stones can be heavy."),("being hard","Stones are hard.")],"Living things respond."),
    ("tf",4,"r4-die","Living things die.",True,"True.")]))
build(dict(S,ch="natures-treasures",topic="saving-water-and-soil",name_en="Saving water and soil",name_ta="நீரையும் மண்ணையும் காத்தல்",
 objectives=["Give ways to save water","Say how soil is lost and saved"],
 story=("The dripping tap","Sara noticed the school tap dripping all day. Her teacher measured: one drop each second made a full bucket in a day.\n\"So much wasted!\" gasped Sara. She tightened the tap and told her class about it."),
 explain=["Fresh water is limited, so we must save it. Close taps, repair leaks, reuse water from washing vegetables for plants, and collect rainwater.","Soil is lost when wind and rain carry it away, especially where there are no plants. Roots of plants and trees hold soil together.","We save soil by planting trees and grass, by terrace farming on slopes and by not cutting forests. Using compost instead of too much chemicals keeps soil healthy."],
 terms=["rainwater harvesting","soil erosion","compost","leak"],
 narr=[("Fresh water is limited. Close taps and repair leaks.","save water"),("Collecting rain water is called rainwater harvesting.","rainwater harvesting"),("Wind and rain can carry soil away. This is soil erosion.","soil erosion"),("Plants and trees hold soil with their roots. Planting more of them saves soil.","trees save soil")],
 ex=("How can a school save water?",[("Repair dripping taps quickly.","A drip wastes much water."),("Collect rain water from the roof.","Use it for plants."),("Teach children to close taps. So saving small amounts adds up.","Small actions matter.")]),
 tb=("A friend says planting trees does not help soil. How will you explain?",["Roots hold the soil in place.","Without plants wind and rain wash soil away."],["Thinking soil stays without plants."]),
 summary=["Save water: close taps, fix leaks, harvest rain.","Soil erosion is soil carried away by wind or water.","Plants and terraces help to save soil."],
 q=[("mcq",1,"r1-tap","A good habit to save water is to","close the tap after use",[("leave the tap running","That wastes water."),("water the road","That wastes water.")],"Every drop counts."),
    ("tf",1,"r1-leak","A dripping tap wastes water.",True,"True."),
    ("mcq",2,"r2-harv","Collecting rain water is called","rainwater harvesting",[("soil erosion","That is loss of soil."),("evaporation","That is water to vapour.")],"We store rain for later."),
    ("tf",2,"r2-eros","Soil erosion means soil being carried away.",True,"True."),
    ("mcq",3,"r3-root","Roots of plants","hold the soil",[("remove the soil","Roots hold it."),("make soil dry","Their job is to hold soil.")],"They bind soil together."),
    ("short",3,"r3-save","Name one way to save soil.",["plant trees","trees","terrace","grass","terraces","planting","compost","plant grass"],"Planting trees and terraces save soil."),
    ("mcq",4,"r4-comp","Compost is made from","kitchen and garden waste",[("plastic bags","Plastic does not rot."),("stones","Stones do not rot.")],"It enriches the soil."),
    ("tf",4,"r4-forest","Cutting forests increases soil erosion.",True,"True.")]))
build(dict(S,ch="beyond-earth",topic="phases-of-the-moon",name_en="Phases of the Moon",name_ta="நிலவின் கலைகள்",
 objectives=["Say why the Moon seems to change shape","Name the new moon and full moon"],
 story=("The shrinking Moon","Anu watched the Moon every night for a month. On one night it was a bright round disc. A week later it was a half circle, and later it was a thin curve.\n\"Is someone eating the Moon?\" she asked.\nHer grandfather laughed. \"No, we only see part of its lit side.\""),
 explain=["The Moon does not make its own light. It shines because sunlight falls on it. Always half of the Moon is lit by the Sun.","The Moon goes round the Earth in about one month. As it moves, we see different amounts of its lit half. These shapes are called phases of the Moon.","On the full moon night we see the whole lit face. On the new moon night we cannot see it. In between it looks like a crescent or a half moon. After the new moon the bright part grows, which is the waxing phase, and after the full moon it shrinks, which is the waning phase."],
 terms=["phase","new moon","full moon","crescent","waxing"],
 narr=[("The Moon has no light of its own. It shines because the Sun lights it.","moon shines by sunlight"),("As the Moon goes round the Earth, we see different parts of its lit side.","moon goes round the Earth"),("These shapes are the phases. Full moon shows the whole lit face. On new moon we cannot see it.","full moon and new moon"),("The cycle of phases takes about one month.","about a month")],
 ex=("Why do we not see the Moon on a new moon night?",[("On a new moon the lit half faces away from us.","The lit side is turned away."),("We see only the dark half, which cannot be seen in the dark sky.","So the Moon seems missing."),("A few days later a thin crescent appears.","The bright part then grows.")]),
 tb=("A friend says the Moon changes shape because the Earth's shadow covers it. How will you explain?",["Phases are caused by how much of the lit half we see as the Moon moves round the Earth.","The Earth's shadow causes a lunar eclipse, which is different."],["Mixing up phases and eclipses."]),
 summary=["The Moon shines by reflected sunlight.","We see different parts of the lit half: the phases.","The cycle takes about a month."],
 q=[("mcq",1,"r1-light","The Moon shines because","sunlight falls on it",[("it makes its own light","It has no light of its own."),("it is on fire","It is a cold rock.")],"It reflects sunlight."),
    ("tf",1,"r1-own","The Moon makes its own light.",False,"False."),
    ("mcq",2,"r2-full","On a full moon night we see","the whole lit face",[("no Moon","That is new moon."),("a thin curve","That is a crescent.")],"The whole lit side faces us."),
    ("tf",2,"r2-month","The phases repeat in about one month.",True,"True."),
    ("mcq",3,"r3-new","On a new moon night the Moon is","not visible",[("full and bright","That is full moon."),("a half circle","That is a half moon.")],"The lit half faces away from us."),
    ("short",3,"r3-name","What is a thin curved Moon called?",["crescent","a crescent","crescent moon"],"It is called a crescent."),
    ("mcq",4,"r4-cause","The phases happen because the Moon","goes round the Earth",[("grows and shrinks","Its size does not change."),("is eaten","Nothing eats it.")],"We see different amounts of its lit side."),
    ("tf",4,"r4-size","The Moon really changes size every night.",False,"False. Only the lit part we see changes.")]))
